/*

    B-spline Integral Demonstration by chronos
    -------------------------------------------------------------------------------------------

    Demonstrating that the integral of a (cardinal) B-spline (basis function) 
    is simply a sum of the one degree higher B-splines from that point.

    The B-splines have the partition of unity property (and equivalently unit integral!)
    so the integral maxes out at 1.

    B-splines can be constructed by repeated convolution of a boxcar/rect function by itself.

    Sorry for the messy and inefficient code ^_^'
    Note: There's also some dead code related to me experimenting with generalized bernstein polynomials
    which I couldn't be bothered to delete, which is interesting, but all the plotted functions are B-splines
    (or sums thereof)

    -------------------------------------------------------------------------------------------
    self link: https://www.shadertoy.com/view/X3KyDt
    -------------------------------------------------------------------------------------------

*/


vec3 draw_slider(vec3 color, float ps, vec2 uv, vec2 slider_a, vec2 slider_b, float slider_pos)
{
    { // shadow
        float d = slider_sdf(slider_a, slider_b, slider_pos, uv-vec2(2, -2)*ps);
        float a = 0.1*smoothstep(5.*ps, -ps, d);
        color  = mix(color, vec3(0), a);
    }

    float d = slider_sdf(slider_a, slider_b, slider_pos, uv);
    float a = smoothstep(ps, -ps, d);
    return mix(color, vec3(0.75), a);
}

float grid_sdf(float grid_cells, vec2 p)
{
    vec2 pi = floor(p*grid_cells);
    vec2 pf = fract(p*grid_cells);

    vec2 dist_xy = min(pf, 1.-pf);
    float dist = min(dist_xy.x, dist_xy.y);
    return dist/grid_cells;
}

vec2 get_slider_states()
{
    vec4 slider0_state = texelFetch(iChannel0, ivec2(0, 0), 0);
    vec4 slider1_state = texelFetch(iChannel0, ivec2(1, 0), 0);
    vec2 slider_states = vec2(slider0_state.r, slider1_state.r);
    if(length(iMouse.xy) < 10.)
    {
        slider_states = vec2(cos(iTime), sin(iTime*.2))*.5+.5;
    }
    return slider_states;
}

float func(float x)
{
    float y = cubic_bspline(x);

    return y;
}


// Integral of quadratic B-spline as sum of cubic B-splines.
// --------------------------------------------------------------------------
// There is a more efficient version based directly on the deBoord algorithm
// at the bottom of the Common tab, quadratic_bspline_integral()
// (It uses the cubic_splnie func instead of cubic_bspline func).
// But keeping this as it is for demonstration. 
// quadratic_bspline_integral() can also be made more efficient by 
// inlining the control point values
float int_func(float x) 
{   
    x = min(x, 3.); // little trick: Since we know it saturates at the last knot vector,
    // we can just clamp it there instead of evaluating the rest of the B-splines
    float y =
        cubic_bspline(x) + 
        cubic_bspline(x-1.) + 
        cubic_bspline(x-2.) + 
        cubic_bspline(x-3.) 

        /*
        +
        cubic_bspline(x-4.) + 
        cubic_bspline(x-5.) + 
        cubic_bspline(x-6.) + 
        cubic_bspline(x-7.)
        */
        ;

    return y;
}

float plot_alpha(float x, vec2 uv, float ps)
{
    float dx = .5*ps;
    float d   = line(vec2(x-dx, func(x-dx)), vec2(x+dx, func(x+dx)), uv);
    return smoothstep(1.5*ps, 0., d);
}

float plot_integral_alpha(float x, vec2 uv, float ps)
{
    float dx = .5*ps;
    float d   = line(vec2(x-dx, int_func(x-dx)), vec2(x+dx, int_func(x+dx)), uv);
    return smoothstep(1.5*ps, 0., d);
}

float hue = -.33;
vec3 plot(vec3 color, vec2 plot_uv, float plot_ps)
{
    float x = plot_uv.x;
    { // graph shadow
        float alpha = plot_alpha(x, plot_uv+vec2(-0.5,2)*plot_ps, plot_ps*5.);
        color  = mix(color, vec3(0), 0.15*alpha);
    }

    vec3 plotcol = .5+.5*cos(2. * PI * (hue + vec3(0, 1, 2)/3.));
    hue += 1./7.;

    float alpha = plot_alpha(x, plot_uv, plot_ps*1.5);
    color = mix(color, vec3(0.9) * plotcol, alpha);
    return color;
}


vec3 plot_integral(vec3 color, vec2 plot_uv, float plot_ps)
{
    float x = plot_uv.x;
    { // graph shadow
        float alpha = plot_integral_alpha(x, plot_uv+vec2(-0.5,2)*plot_ps, plot_ps*5.);
        color  = mix(color, vec3(0), 0.15*alpha);
    }
    float alpha = plot_integral_alpha(x, plot_uv, plot_ps*1.5);
    color = mix(color, vec3(0.9), alpha);
    return color;
}

float plot_quadratic_alpha(float x, vec2 uv, float ps)
{
    float dx = .5*ps;
    float d   = line(vec2(x-dx, quadratic_bspline(x-dx)), vec2(x+dx, quadratic_bspline(x+dx)), uv);
    return smoothstep(1.5*ps, 0., d);
}
vec3 plot_quadratic(vec3 color, vec2 plot_uv, float plot_ps)
{
    float x = plot_uv.x;
    { // graph shadow
        float alpha = plot_quadratic_alpha(x, plot_uv+vec2(-0.5,2)*plot_ps, plot_ps*5.);
        color  = mix(color, vec3(0), 0.15*alpha);
    }
    float alpha = plot_quadratic_alpha(x, plot_uv, plot_ps*1.5);
    color = mix(color, vec3(0.1), alpha);
    return color;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;
    vec2 mouse  = (2.*iMouse.xy-iResolution.xy)/iResolution.y;
    //vec2 mouse2 = (2.*abs(iMouse.zw)-iResolution.xy)/iResolution.y;
    float ps = 2./iResolution.y;

    vec3 color = vec3(.5);

    float border = smoothstep(1.33, .99, abs(uv.x)) * smoothstep(1.33, .99, abs(uv.y));

    vec2 slider_states = get_slider_states();
    float slider_pos0 = slider_states.x;
    float slider_pos1 = slider_states.y;

    vec2 origin = vec2(-0.875, -.8) + vec2(4. * (slider_pos0-1.), 0);

    { // Draw plot

        float plot_ps = ps * zoom;
        vec2 plot_uv  = (uv-origin) * zoom;

        { // draw grid 
            float d = grid_sdf(4., plot_uv);
            float a = smoothstep(1.5*plot_ps, .5*plot_ps, d);
            color = mix(color, vec3(0.25), .75*a * mix(0.25, 1., border));
        }

        { // Draw axes
            float axes = min(seg(vec2(0), vec2(1.01,0), plot_uv), seg(vec2(0), vec2(0,1.01), plot_uv)) - 2.5*plot_ps;
            float axes_alpha = smoothstep(plot_ps, -plot_ps, axes);
            color = mix(color, vec3(.2), .75*axes_alpha);
        }

        vec3 plot_color = color;
        plot_color = plot(plot_color,  plot_uv,  plot_ps);
        plot_color = plot(plot_color,  plot_uv - vec2(1,0),  plot_ps);
        plot_color = plot(plot_color,  plot_uv - vec2(2,0),  plot_ps);
        plot_color = plot(plot_color,  plot_uv - vec2(3,0),  plot_ps);
        plot_color = plot(plot_color,  plot_uv - vec2(4,0),  plot_ps);
        plot_color = plot(plot_color,  plot_uv - vec2(5,0),  plot_ps);

        plot_color = plot_integral(plot_color,  plot_uv,  plot_ps);

        plot_color = plot_quadratic(plot_color,  plot_uv,  plot_ps);

        color = mix(color, plot_color, mix(0.5, 1., border)); // fade

    }

    color *= 1.-dot(uv, uv)*.03; // vignette

    color = draw_slider(color, ps, uv, slider0_a, slider0_b, slider_pos0);
    //color = draw_slider(color, ps, uv, slider1_a, slider1_b, slider_pos1);

    fragColor = vec4(sRGBencode(color) 
            + 2./256.*(texelFetch(iChannel3, (ivec2(fragCoord)+iFrame*101)%1024, 0).rgb-.5)
        ,
        1);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;
    vec2 mouse = (2.*iMouse.xy-iResolution.xy)/iResolution.y;
    //vec2 mouse2 = (2.*abs(iMouse.zw)-iResolution.xy)/iResolution.y;

    float mouse_down = step(0., iMouse.z);
    float ps = 2./iResolution.y;

    vec4 state = vec4(0);

    vec4 bufA = texelFetch(iChannel0, ivec2(fragCoord), 0);

    if(iFrame > 0)
        state = bufA;

    ivec2 coord = ivec2(fragCoord);
    if(coord == ivec2(0))
    {        
        float slider_pos = clamp(dot(slider0_ab, mouse-slider0_a)/dot(slider0_ab, slider0_ab), 0., 1.);

        vec2 slider_handle = mix(slider0_a, slider0_b, slider_pos);

        float mouse_handle_dist = length(slider_handle - mouse) - slider_handle_size;

        float handle_hover = step(mouse_handle_dist, 0.);

        float handle_pressed = float(state.g== 1.);

        handle_pressed = mouse_down * max(handle_pressed, handle_hover);

        state.g = handle_pressed;

        state.r = mix(state.r, slider_pos, handle_pressed);

    }

    if(coord == ivec2(1, 0))
    {        
        float slider_pos = clamp(dot(slider1_ab, mouse-slider1_a)/dot(slider1_ab, slider1_ab), 0., 1.);

        vec2 slider_handle = mix(slider1_a, slider1_b, slider_pos);

        float mouse_handle_dist = length(slider_handle - mouse) - slider_handle_size;

        float handle_hover = step(mouse_handle_dist, 0.);

        float handle_pressed = float(state.g == 2.);

        handle_pressed = mouse_down * max(handle_pressed, handle_hover);

        state.g = handle_pressed * 2.;

        state.r = mix(state.r, slider_pos, handle_pressed);

    }


    fragColor = state;
}

const float PI = 3.14159265;
float sRGBencode(float C_linear) { return C_linear > 0.0031308 ? (1.055 * pow(C_linear, 1./2.4) - 0.055) : (12.92 * C_linear); }
vec3 sRGBencode(vec3 C_linear) { C_linear = clamp(C_linear, 0., 1.); return vec3(sRGBencode(C_linear.x), sRGBencode(C_linear.y), sRGBencode(C_linear.z)); }
float seg(vec2 a, vec2 b, vec2 p) { p-=a; b-=a; return length(clamp(dot(p,b)/dot(b,b), 0., 1.)*b - p); }
float line(vec2 a, vec2 b, vec2 p) { p-=a; b-=a; return length((dot(p,b)/dot(b,b))*b - p); }

float zoom = 1.;

// Slider parameters
const float slider_size = 0.01;
const float slider_handle_size = 0.03;

const vec2 slider0_a = vec2(-1, -.866);
const vec2 slider0_b = vec2( 1, -.866);
const vec2 slider0_ab = slider0_b - slider0_a;

const vec2 slider1_a = vec2( 1.05, -.79);
const vec2 slider1_b = vec2( 1.05,  .93);
const vec2 slider1_ab = slider1_b - slider1_a;
// End of slider parameters


float slider_sdf(vec2 a, vec2 b, float handle_pos, vec2 p)
{
    float sdf = seg(a, b, p) - slider_size;
    vec2 slider_handle_pos = mix(a, b, handle_pos);
    sdf = min(sdf, length(p-slider_handle_pos) - slider_handle_size);
    sdf = max(sdf, slider_handle_size*.75 - length(slider_handle_pos-p));
    return sdf;
}


float imix(float y, float a, float b) { return (y-a)/(b-a); }

float remap(float a0, float b0, float x, float a1, float b1)
{
    return mix(a1, b1, imix(x, a0, b0));
}

float binomial_coefficient(in float n, in float k) {
    if(k < 0.0 || k > n) return 0.0;
    if(k == 0.0 || k == n) return 1.0;
    k = min(k, n-k);
    float c = 1.0;
    for(float i = 0.0; i > 0.0; i++) {
        if(i >= k) break;
        c = (c*(n-i)) / (i+1.0);
    }
    return c;
}

float bernstein(in float n, in float k, in float x) {
    return binomial_coefficient(n, k) * pow(x, k) * pow(1.0-x, n-k);
}

float stirlings_approximation(float x)
{
    return sqrt(2. * PI * x) * pow(x/exp(1.), x);
}

float stirlings_approximation_modified(float x)
{
    return stirlings_approximation(x)+0.925/(15.*x+1.);
}

float generalized_binomial_coefficient(float n, float k) {
    if(k  < 0.0 ||  k > n) return 0.0;
    if(k == 0.0 || k == n) return 1.0;

    float n_fac = stirlings_approximation_modified(n);
    float k_fac = stirlings_approximation_modified(k);
    float nk_fac = stirlings_approximation_modified(n-k);

    return n_fac/(k_fac * nk_fac);
}

float generalized_bernstein(in float n, in float k, in float x) {
    return generalized_binomial_coefficient(n, k) * pow(x, k) * pow(1.0-x, n-k);
}

float ilerp(float a, float b, float c)
{
    float t = (c-a) / (b-a);
    return t;
}

float cubic_spline(vec4 C, float x)
{
    float[6] t = float[6](0., 1., 2., 3., 4., 5.); // knot vector
    const int d = 3;
    vec3 C1 = vec3(
        mix(C[0], C[1], ilerp(t[0], t[0+d], x)),
        mix(C[1], C[2], ilerp(t[1], t[1+d], x)),
        mix(C[2], C[3], ilerp(t[2], t[2+d], x))
    );

    vec2 C2 = vec2(
        mix(C1[0], C1[1], ilerp(t[1], t[1+d-1], x)),
        mix(C1[1], C1[2], ilerp(t[2], t[2+d-1], x))
    );

    float C3 = mix(C2[0], C2[1], ilerp(t[2], t[2+d-2], x));

    return C3 * (step(t[2], x) - step(t[3], x));
}


float cubic_bspline(float x)
{
    return 
        cubic_spline(vec4(1,0,0,0), x-1.)+
        cubic_spline(vec4(0,1,0,0), x-0.)+
        cubic_spline(vec4(0,0,1,0), x+1.)+
        cubic_spline(vec4(0,0,0,1), x+2.);
}



float quadratic_spline(vec3 C, float x)
{
    float[4] t = float[4](0., 1., 2., 3.); // knot vector
    const int d = 2;
    vec2 C1 = vec2(
        mix(C[0], C[1], ilerp(t[0], t[0+d], x)),
        mix(C[1], C[2], ilerp(t[1], t[1+d], x))
    );

    float C2 = (
        mix(C1[0], C1[1], ilerp(t[1], t[1+d-1], x))
    );

    return C2 * (step(t[1], x) - step(t[2], x));
}


float quadratic_bspline(float x)
{
    return 
        quadratic_spline(vec3(1,0,0), x-1.)+
        quadratic_spline(vec3(0,1,0), x-0.)+
        quadratic_spline(vec3(0,0,1), x+1.);
}

float quadratic_bspline_integral(float x)
{
     // Note that the quadratic bspline integral is made from cubics
    return 
        cubic_spline(vec4(1,1,1,1), x-1.)+ // this is just a boxcar funtion, can be replaced by step(a,x)-step(b,x)
        cubic_spline(vec4(0,1,1,1), x-0.)+
        cubic_spline(vec4(0,0,1,1), x+1.)+
        cubic_spline(vec4(0,0,0,1), x+2.);

    // Can also be made more efficient by inlining the control point values, since it's just constant 0s and 1s
}
